import { createHash, randomUUID } from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';
import { Transform, type Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { AppError, badRequest } from './errors.js';

/**
 * File storage on local disk. The database only ever stores a *storage key*
 * (a '/'-separated path relative to the storage root). Keys are generated by
 * the server, never taken from user input, and every resolve is checked to
 * stay inside the root — so uploaded filenames can't escape it.
 */

export type FileKind = { fileType: string; mimeType: string; ext: string };

const KINDS: Record<string, FileKind & { magic: (b: Buffer) => boolean }> = {
  pdf: { fileType: 'PDF', mimeType: 'application/pdf', ext: 'pdf', magic: (b) => b.subarray(0, 5).toString('latin1') === '%PDF-' },
  docx: {
    fileType: 'DOCX',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    ext: 'docx',
    magic: isZip,
  },
  xlsx: {
    fileType: 'XLSX',
    mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    ext: 'xlsx',
    magic: isZip,
  },
  png: { fileType: 'PNG', mimeType: 'image/png', ext: 'png', magic: (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) },
  jpg: { fileType: 'JPEG', mimeType: 'image/jpeg', ext: 'jpg', magic: isJpeg },
  jpeg: { fileType: 'JPEG', mimeType: 'image/jpeg', ext: 'jpeg', magic: isJpeg },
};

function isZip(b: Buffer) {
  return b.length >= 4 && b[0] === 0x50 && b[1] === 0x4b && b[2] === 0x03 && b[3] === 0x04;
}
function isJpeg(b: Buffer) {
  return b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff;
}

export const ALLOWED_EXTENSIONS = Object.keys(KINDS);

/** Strip directories, control chars and characters Windows forbids; keep it readable. */
export function sanitizeFileName(name: string): string {
  const base = name.split(/[\\/]/).pop() ?? '';
  const cleaned = base
    .normalize('NFKC')
    .replace(/[\x00-\x1f\x7f<>:"|?*]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^[.\s]+/, '')
    .trim();
  const reserved = /^(con|prn|aux|nul|com\d|lpt\d)(\..*)?$/i;
  const safe = reserved.test(cleaned) ? `_${cleaned}` : cleaned;
  return safe.slice(-150) || 'file';
}

export function kindForName(name: string) {
  const ext = path.extname(name).slice(1).toLowerCase();
  return KINDS[ext];
}

export class Storage {
  constructor(public readonly root: string) {}

  async init() {
    await fs.mkdir(this.root, { recursive: true });
  }

  /** Resolve a storage key to an absolute path, refusing anything outside the root. */
  resolve(key: string): string {
    if (!key || key.includes('\0') || path.isAbsolute(key)) throw new AppError(400, 'INVALID_PATH', 'Invalid storage key');
    const abs = path.resolve(this.root, ...key.split('/'));
    const rel = path.relative(this.root, abs);
    if (rel.startsWith('..') || path.isAbsolute(rel)) throw new AppError(400, 'INVALID_PATH', 'Invalid storage key');
    return abs;
  }

  /**
   * Stream an upload to disk under `dir`, enforcing size limits and verifying
   * the file's real content type (magic bytes) matches its extension.
   */
  async saveUpload(dir: string, originalName: string, stream: Readable & { truncated?: boolean }, maxBytes: number) {
    const safeName = sanitizeFileName(originalName);
    const kind = kindForName(safeName);
    if (!kind) {
      stream.resume();
      throw badRequest(`File type not allowed. Allowed: ${ALLOWED_EXTENSIONS.join(', ')}`);
    }

    const storedName = `${randomUUID()}.${kind.ext}`;
    const key = `${dir}/${storedName}`;
    const abs = this.resolve(key);
    await fs.mkdir(path.dirname(abs), { recursive: true });

    const hash = createHash('sha256');
    let size = 0;
    let head = Buffer.alloc(0);
    const meter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        size += chunk.length;
        if (size > maxBytes) return cb(new AppError(413, 'FILE_TOO_LARGE', `File exceeds ${Math.round(maxBytes / 1024 / 1024)} MB limit`));
        if (head.length < 16) head = Buffer.concat([head, chunk.subarray(0, 16 - head.length)]);
        hash.update(chunk);
        cb(null, chunk);
      },
    });

    try {
      await pipeline(stream, meter, createWriteStream(abs));
      if (stream.truncated) throw new AppError(413, 'FILE_TOO_LARGE', `File exceeds ${Math.round(maxBytes / 1024 / 1024)} MB limit`);
      if (size === 0) throw badRequest('File is empty');
      if (!kind.magic(head)) throw badRequest(`File content does not match the .${kind.ext} extension`);
    } catch (err) {
      await fs.rm(abs, { force: true });
      throw err;
    }

    return { key, storedName, safeName, sizeBytes: size, sha256: hash.digest('hex'), fileType: kind.fileType, mimeType: kind.mimeType };
  }

  /** Write generated content (exports, reports). Used by later phases. */
  async saveBuffer(dir: string, fileName: string, data: Buffer) {
    const safeName = sanitizeFileName(fileName);
    const key = `${dir}/${randomUUID()}-${safeName}`;
    const abs = this.resolve(key);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, data);
    return { key, sizeBytes: data.length, sha256: createHash('sha256').update(data).digest('hex') };
  }

  async verify(key: string, sha256: string) {
    const abs = this.resolve(key);
    const hash = createHash('sha256');
    await pipeline(createReadStream(abs), hash);
    return hash.digest('hex') === sha256;
  }

  async exists(key: string) {
    try {
      await fs.access(this.resolve(key));
      return true;
    } catch {
      return false;
    }
  }

  read(key: string) {
    return createReadStream(this.resolve(key));
  }

  readBuffer(key: string) {
    return fs.readFile(this.resolve(key));
  }

  /** Only for temporary files (e.g. document inspection); stored documents are never deleted. */
  async removeTemp(key: string) {
    if (!key.startsWith('tmp/')) throw new AppError(400, 'INVALID_PATH', 'Only temporary files can be removed');
    await fs.rm(this.resolve(key), { force: true });
  }
}

/** RFC 6266 Content-Disposition header that survives non-ASCII names. */
export function contentDisposition(fileName: string) {
  const ascii = fileName.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(fileName)}`;
}
